-- SQL scripts for implementing the schemas
-- Generated by ChatGPT 21/10/2026

-- Database creation
CREATE DATABASE Phan_23028920;
USE Phan_23028920;

CREATE TABLE Year (
    year INT NOT NULL,
    PRIMARY KEY (year)
);

CREATE TABLE Region (
    regionId INT NOT NULL,
    name VARCHAR(50) NOT NULL,
    PRIMARY KEY (regionId)
);

CREATE TABLE Province (
    provinceId INT NOT NULL,
    name VARCHAR(50) NOT NULL,
    regionId INT NOT NULL,
    PRIMARY KEY (provinceId),
    FOREIGN KEY (regionId) REFERENCES Region(regionId)
);

CREATE TABLE Country (
    countryId INT NOT NULL,
    name VARCHAR(50) NOT NULL,
    continent VARCHAR(50),
    PRIMARY KEY (countryId)
);

CREATE TABLE TransportMode (
    transportId INT NOT NULL,
    mode VARCHAR(50) NOT NULL,
    PRIMARY KEY (transportId)
);

CREATE TABLE ExpenditureCategory (
    categoryId INT NOT NULL,
    category VARCHAR(50) NOT NULL,
    PRIMARY KEY (categoryId)
);

CREATE TABLE TouristType (
    typeId INT NOT NULL,
    type VARCHAR(50) NOT NULL,
    PRIMARY KEY (typeId)
);


-- Relationship tables

-- M:N between Year and Country
CREATE TABLE ArrivalByNationality (
    year INT NOT NULL,
    countryId INT NOT NULL,
    arrivalCount INT UNSIGNED NOT NULL,

    PRIMARY KEY (year, countryId),

    FOREIGN KEY (year) REFERENCES Year(year),
    FOREIGN KEY (countryId) REFERENCES Country(countryId)
);

-- M:N between Year and TransportMode
CREATE TABLE ArrivalByTransport (
    year INT NOT NULL,
    transportId INT NOT NULL,
    arrivalCount INT UNSIGNED NOT NULL,

    PRIMARY KEY (year, transportId),

    FOREIGN KEY (year) REFERENCES Year(year),
    FOREIGN KEY (transportId) REFERENCES TransportMode(transportId)
);

-- M:N between Year and Province
CREATE TABLE ProvincialTurnover (
    year INT NOT NULL,
    provinceId INT NOT NULL,
    turnoverAmount DECIMAL(15,2) NOT NULL,

    PRIMARY KEY (year, provinceId),

    FOREIGN KEY (year) REFERENCES Year(year),
    FOREIGN KEY (provinceId) REFERENCES Province(provinceId),

    CHECK (turnoverAmount >= 0)
);

-- Ternary relationship between Year, ExpenditureCategory and TouristType
CREATE TABLE ExpenditureByCategory (
    year INT NOT NULL,
    categoryId INT NOT NULL,
    typeId INT NOT NULL,
    expenditureAmount DECIMAL(15,2) NOT NULL,
    currency CHAR(3) NOT NULL,

    PRIMARY KEY (year, categoryId, typeId),

    FOREIGN KEY (year) REFERENCES Year(year),
    FOREIGN KEY (categoryId)
        REFERENCES ExpenditureCategory(categoryId),
    FOREIGN KEY (typeId)
        REFERENCES TouristType(typeId),

    CHECK (expenditureAmount >= 0)
);
